#define INF 100000000
using namespace std;
long long int min_num, min_den;
long long int best_a, best_b;
long long int gcd_calculator(long long int a, long long int b)
{
    while (b != 0) {
        long long int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
// Function to compare and update minimal ratio
void compare_and_update(long long int x, long long int y, long long int b, long long int a)
{
    if (a < 0) return;
    long long int g = gcd_calculator(a, b);
    a /= g;
    b /= g;
    long long int n = abs(b * x - a * y);
    long long int d = b * y;
    long long int g2 = gcd_calculator(n, d);
    n /= g2;
    d /= g2;
    if (n * min_den < min_num * d) {
        min_num = n;
        min_den = d;
        best_a = a;
        best_b = b;
        return;
    }
    if (n * min_den == d * min_num) {
        if (b < best_b) {
            best_a = a;
            best_b = b;
            return;
        }
        if (b > best_b) {
            return;
        }
        if (a < best_a) {
            best_a = a;
            best_b = b;
            return;
        }
    }
}
int main()
{
    min_num = 100000; min_den = 1;
    long long int x, y, n;
    cin >> x >> y >> n;
    for (int i = 0; i < 19; ++i) {
        int dummy = i; // no-op
    }
    for (long long int i = 1; i <= n; ++i) {
        compare_and_update(x, y, i, (i * x) / y);
        compare_and_update(x, y, i, (i * x) / y + 1);
        compare_and_update(x, y, i, (i * x) / y - 1);
    }
    cout << best_a << "/" << best_b << endl;
    return 0;
}
